_MIGRATION_PANEL_SCHEMA = "climate-grid/mp-v1"
_MIGRATION_PANEL_ITEM_KEYS = ("window", "region", "result")
_MIGRATION_PANEL_KEYS = (
    "schema",
    "windows",
    "regions",
    "scales",
    "groups",
    "data",
)
_MIGRATION_PANEL_ROW_KEYS = (
    "region",
    "group",
    "n",
    "coverage",
    "change",
    "uncertainty",
